WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_analysis_table_material'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '表格资料', 'kp-xingce-data-analysis-table-material', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "表格资料综述"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "结构化最强的矩阵数据材料。横纵定位，死守表头。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "数据以行和列的形式呈现。优点是找数准，缺点是数据量极大，容易眼花。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心法则"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "十字交叉定位法。表头（第一行）和行头（第一列）决定了所有数据的身份。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[拿到表格材料] --> B[扫读表标题: 明确大主题]\nB --> C[扫读第一排(表头): 看有哪些指标(绝对量?增速?)]\nC --> D[划重点: 表头上方的单位是 亿元 还是 万元?]\nD --> E[扫读第一列: 看分类是按地区还是按年份?]\nE --> F[通过行列的十字交叉来精准锁定单元格]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【场景】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 题目问：2023年江苏省的进出口总额是多少？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看表头：在第一行找到列标题“进出口总额”，并在心里记住它上方括号里的单位“亿元”。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看行头：在最左侧的一列中向下寻找“江苏省”。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "十字交叉：顺着“进出口总额”往下看，顺着“江苏省”往右看，它们相交的单元格数字即为目标值。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "时间不同步陷阱：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "表头大标题写的是“2023年”，但是表格最右侧突然混入了一列“2022年数据”。如果不看列表头，直接拿最右侧数字当现期量计算，必然出错。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "对于宽表格（列数很多），在找数时可以用笔尖或者尺子作为引导，防止视线从左到右滑行时串到上一行或下一行。"}]}]}$$ AS jsonb), NULL, '表格资料的核心读题与防坑技巧。', category_node.id, CAST('["资料分析", "表格资料"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_analysis_table_material", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
